import {getRegion} from './region.js?v=8.14';
import {esc,local,num} from './marine-charts.js?v=8.14';
import {habitatFrame,habitatTileURL,decodeHabitatTile,habitatTileMatchesLayer,tileOverlaps,habitatColor,thermalReference,validHabitatManifest} from './habitat-data.js?v=8.14';

const names={'sst-analysis':'Satellite temperature analysis','chlorophyll-observation':'Satellite chlorophyll','wcofs-surface-forecast':'NOAA temperature & surface flow'};
const roundTime=t=>local(t,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
export function initHabitatDynamics(map,protectedAreas,onSelect) {
  const region=getRegion(),cache=new Map();let product=null,base=region.habitat_feed,state=null,mode='auto',generation=0,rows=[],current=null,fields=[],step=[],controller=null,loading=false;
  const controls=document.createElement('div');controls.className='habitat-map-options';
  controls.innerHTML='<label for="habitat-layer">Ocean habitat layer<select id="habitat-layer"><option value="auto">Auto · ocean forecast for pelagic targets</option><option value="off">Off</option><option value="forecast">Temperature & surface flow · forecast</option><option value="temperature">Satellite temperature · dated analysis</option><option value="fronts">Temperature gradient · dated analysis</option><option value="chlorophyll">Chlorophyll · dated observation</option></select></label><p class="small">Use the Conditions timeline to choose your trip time. Ocean forecasts cover their actual three-day horizon; satellite layers keep their observation date.</p>';
  document.getElementById('weather-map-options').after(controls);
  const status=L.control({position:'bottomleft'});let statusBox;
  status.onAdd=()=>{statusBox=L.DomUtil.create('div','habitat-map-key');statusBox.setAttribute('role','status');statusBox.hidden=true;L.DomEvent.disableClickPropagation(statusBox);return statusBox;};status.addTo(map);
  const pane=map.createPane('habitatWater');pane.style.zIndex=350;pane.style.pointerEvents='none';
  const Canvas=L.Layer.extend({onAdd(){this.canvas=L.DomUtil.create('canvas','habitat-water-canvas',pane);this.canvas.setAttribute('aria-hidden','true');this.canvas.style.pointerEvents='none';map.on('moveend zoomend resize',this.draw,this);this.draw();},onRemove(){map.off('moveend zoomend resize',this.draw,this);this.canvas.remove();},draw(){
    const size=map.getSize(),ratio=Math.min(devicePixelRatio||1,2),canvas=this.canvas;canvas.width=size.x*ratio;canvas.height=size.y*ratio;canvas.style.width=size.x+'px';canvas.style.height=size.y+'px';L.DomUtil.setPosition(canvas,map.containerPointToLayerPoint([0,0]));
    const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);const latStep=step[0]/2,lonStep=step[1]/2;
    const valueIndex=fields.indexOf(mode==='chlorophyll'?'chlorophyll_mg_m3':mode==='fronts'?'temperature_gradient_c_per_km':'temperature_c');
    for(const row of rows){const color=habitatColor(row[valueIndex],mode);if(!color)continue;
      const a=map.latLngToContainerPoint([row[0]+latStep,row[1]-lonStep]),b=map.latLngToContainerPoint([row[0]-latStep,row[1]+lonStep]);ctx.fillStyle=color;ctx.globalAlpha=.48;ctx.fillRect(a.x,a.y,b.x-a.x+.4,b.y-a.y+.4);
    }
    if(current?.id==='wcofs-surface-forecast') {const u=fields.indexOf('u_mps'),v=fields.indexOf('v_mps');ctx.globalAlpha=.85;ctx.strokeStyle='#103746';ctx.lineWidth=1.4;const seen=new Set();for(const row of rows){if(!Number.isFinite(row[u])||!Number.isFinite(row[v]))continue;const p=map.latLngToContainerPoint(row.slice(0,2)),bucket=`${Math.floor(p.x/45)},${Math.floor(p.y/45)}`;if(seen.has(bucket))continue;seen.add(bucket);const speed=Math.hypot(row[u],row[v]);if(speed<.015)continue;const dx=row[u]/speed*9,dy=-row[v]/speed*9;ctx.beginPath();ctx.moveTo(p.x-dx,p.y-dy);ctx.lineTo(p.x+dx,p.y+dy);ctx.lineTo(p.x+dx-dx*.5+dy*.4,p.y+dy-dy*.5-dx*.4);ctx.moveTo(p.x+dx,p.y+dy);ctx.lineTo(p.x+dx-dx*.5-dy*.4,p.y+dy-dy*.5+dx*.4);ctx.stroke();}}
  }});const canvas=new Canvas().addTo(map);
  function activeId(){const species=document.getElementById('species-select').value;const target=region.target_options.find(t=>t.id===species);if(mode==='off'||mode==='auto'&&!['offshore','pelagic'].includes(target?.kind))return null;return mode==='chlorophyll'?'chlorophyll-observation':['temperature','fronts'].includes(mode)?'sst-analysis':'wcofs-surface-forecast';}
  function message(title,body){const expanded=statusBox.querySelector('details')?.open||false;statusBox.hidden=false;statusBox.innerHTML=`<details${expanded?' open':''}><summary>${esc(title)}</summary><span>${esc(body)}</span></details>`;}
  async function render(){
    const run=++generation;document.dispatchEvent(new CustomEvent('skippercast:ocean-cells',{detail:null}));controller?.abort();controller=new AbortController();rows=[];canvas.draw();const id=activeId();if(!id){statusBox.hidden=true;return;}
    const layer=product?.layers?.[id],clock=habitatFrame(layer,state?.time??Date.now()/1000);current=layer;
    if(!clock.frame){message(names[id],clock.reason+(id==='wcofs-surface-forecast'?' · Choose an earlier time or dated satellite context in Map options.':''));return;}
    const view=map.getBounds(),bounds=[view.getWest(),view.getSouth(),view.getEast(),view.getNorth()],tiles=layer.tiles.filter(t=>tileOverlaps(t.bounds,bounds));
    if(tiles.length>20){message(names[id],'Zoom closer to load the source-resolution ocean grid.');return;}
    if(!tiles.length){message(names[id],'No published cells in this view. Pan within the regional coverage.');return;}
    message(names[id],`Loading ${tiles.length} ocean tiles…`);let failures=0;
    const loaded=await Promise.all(tiles.map(async record=>{try{if(cache.has(record.sha256)&&habitatTileMatchesLayer(cache.get(record.sha256),layer))return cache.get(record.sha256);const url=habitatTileURL(base,record,region.id),response=await fetch(url,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(18000)])});if(!response.ok)throw Error('Ocean tile unavailable');if(Number(response.headers.get('content-length'))>record.bytes)throw Error('Unexpected tile size');const tile=await decodeHabitatTile(await response.arrayBuffer(),record,region.id,id,layer);cache.set(record.sha256,tile);while(cache.size>24)cache.delete(cache.keys().next().value);return tile;}catch{failures++;return null;}}));
    if(run!==generation)return;fields=layer.fields;step=layer.resolution_degrees;
    rows=loaded.filter(Boolean).flatMap(t=>t.frames.find(f=>f.time===clock.frame.time)?.cells||[]).filter(r=>r[0]>=bounds[1]-step[0]&&r[0]<=bounds[3]+step[0]&&r[1]>=bounds[0]-step[1]&&r[1]<=bounds[2]+step[1]);
    if(!rows.length&&failures){message(names[id],'Ocean tile downloads failed. Refresh to retry; no conditions are inferred for missing tiles.');return;}
    if(!rows.length){message(names[id],`${roundTime(clock.frame.time)} · No usable ${mode==='fronts'?'temperature gradients':'cells'} in this view at this time. Missing coverage remains blank.`);canvas.draw();return;}
    if(rows.length>30000){rows=[];message(names[id],'Zoom closer to inspect the full native grid; no lower-resolution fish hotspots are inferred.');canvas.draw();return;}
    document.dispatchEvent(new CustomEvent('skippercast:ocean-cells',{detail:{regionId:region.id,layerId:id,time:clock.frame.time,selectedTime:state?.time??Date.now()/1000,rows,fields,step,sourceURL:layer.source_url,issuedAt:layer.issued_at}}));
    const resolution=step.map(d=>Number(d.toFixed(4))).join('° × ')+'°',age=Math.max(0,(Date.now()/1000-clock.frame.time)/3600),dated=clock.mode==='observed-context';
    const legend=mode==='chlorophyll'?'0.01–10 mg/m³ · blue → green':mode==='fronts'?'0–0.5+ °C/km · blue → orange; analysis uncertainty applies':'50–81°F · blue → red';
    message(`${names[id]} · ${roundTime(clock.frame.time)}`,`${dated?`Dated context · ${Math.round(age)} h old`:'Selected forecast frame'} · ${resolution} native coordinate grid · ${legend}${failures?` · ${failures} tile(s) unavailable`:''}${layer.status==='retained'?' · refresh failed; retained source':''}. Tap water for details.`);canvas.draw();
  }
  map.on('moveend',render);
  map.on('click',event=>{
    if(!rows.length||event.originalEvent?.target?.closest?.('.leaflet-marker-icon,.leaflet-interactive,.leaflet-popup,.leaflet-control'))return;
    const row=rows.find(r=>Math.abs(r[0]-event.latlng.lat)<=step[0]/2&&Math.abs(r[1]-event.latlng.lng)<=step[1]/2);if(!row)return;
    const value=k=>row[fields.indexOf(k)],temp=value('temperature_c'),u=value('u_mps'),v=value('v_mps'),species=state?.species||document.getElementById('species-select').value,method=product.species_methods?.[species],clock=habitatFrame(current,state?.time??Date.now()/1000),protection=protectedAreas.inspect({geometry:{type:'Polygon',coordinates:[[[row[1]-step[1]/2,row[0]-step[0]/2],[row[1]+step[1]/2,row[0]-step[0]/2],[row[1]+step[1]/2,row[0]+step[0]/2],[row[1]-step[1]/2,row[0]+step[0]/2],[row[1]-step[1]/2,row[0]-step[0]/2]]]}});
    if(!clock.frame){render();return;}
    const box=document.createElement('div');box.className='ocean-cell-detail';box.innerHTML=`<strong>${esc(names[current.id])}</strong><p>${esc(roundTime(clock.frame.time))} · ${esc(clock.mode==='forecast'?'modeled surface':'dated surface context')}</p><dl>${Number.isFinite(temp)?`<dt>Temperature</dt><dd>${num(temp*9/5+32)}°F</dd>`:''}${Number.isFinite(value('analysis_error_c'))?`<dt>Analysis standard error</dt><dd>${num(value('analysis_error_c'))}°C</dd>`:''}${Number.isFinite(value('temperature_gradient_c_per_km'))?`<dt>Local temperature gradient</dt><dd>${num(value('temperature_gradient_c_per_km'),3)} °C/km</dd>${fields.includes('thermal_contrast_supported')?`<dt>Product-error screen</dt><dd>${value('thermal_contrast_supported')===1?'Contrast exceeds errors':value('thermal_contrast_supported')===0?'Contrast within errors':'Unavailable'}</dd>`:''}`:''}${Number.isFinite(u)&&Number.isFinite(v)?`<dt>Surface flow</dt><dd>${num(Math.hypot(u,v)*1.94384)} kt toward ${Math.round((Math.atan2(u,v)*180/Math.PI+360)%360)}° true</dd>`:''}${Number.isFinite(value('chlorophyll_mg_m3'))?`<dt>Chlorophyll</dt><dd>${num(value('chlorophyll_mg_m3'),2)} mg/m³</dd>`:''}</dl><p>${esc(thermalReference(method,temp))}</p>${method?`<p class="small">${esc(method.range_meaning)}</p>`:''}<p class="small">${esc(protection.status==='excluded'?'Excluded from fishing targets: '+protection.names.join(', '):protection.status==='unavailable'?'Protected-area check unavailable.':'Protected-area boundary screen clear; species rules still apply.')} Surface flow is not bottom current or boat drift. Temperature edges and chlorophyll do not confirm bait or fish.</p>`;
    if(method?.source_url?.startsWith('https://')){const a=document.createElement('a');a.href=method.source_url;a.target='_blank';a.rel='noopener';a.textContent='Species evidence ↗';box.append(a);}
    const sourceNote=document.createElement('p');sourceNote.className='small';sourceNote.textContent=`${current.kind==='forecast'?'Model initialized':'Source valid'} ${new Date(current.issued_at||current.sample_at).toLocaleString('en-US',{timeZone:region.timezone})} · ${current.valid_cells.toLocaleString()} / ${current.total_cells.toLocaleString()} valid regional cells across published frames. Blank pixels remain unknown.`;box.append(sourceNote);if(current.source_url?.startsWith('https://')){const link=document.createElement('a');link.href=current.source_url;link.target='_blank';link.rel='noopener';link.textContent='Ocean data source ↗';box.append(link);}
    const button=document.createElement('button');button.textContent='Conditions near this water';button.onclick=()=>{onSelect({latitude:row[0],longitude:row[1],label:'Ocean grid sample',geometry:{type:'Polygon',coordinates:[[[row[1]-step[1]/2,row[0]-step[0]/2],[row[1]+step[1]/2,row[0]-step[0]/2],[row[1]+step[1]/2,row[0]+step[0]/2],[row[1]-step[1]/2,row[0]+step[0]/2],[row[1]-step[1]/2,row[0]-step[0]/2]]]}});map.closePopup();document.querySelector('[data-nav="forecast"]').click();};box.append(button);
    L.popup({maxWidth:330}).setLatLng(event.latlng).setContent(box).openOn(map);
  });
  controls.querySelector('select').addEventListener('change',e=>{mode=e.target.value;render();});
  document.addEventListener('skippercast:forecast',e=>{state=e.detail;render();});document.addEventListener('skippercast:species',()=>render());
  async function load(){if(loading)return;loading=true;for(const url of [`/api/habitat?region=${region.id}`,region.habitat_feed,`regions/${region.id}/habitat-dynamics.json`].filter(Boolean)){try{const response=await fetch(url,{signal:AbortSignal.timeout(12000),cache:'no-cache'});if(!response.ok)continue;const data=await response.json();if(!validHabitatManifest(data,region.id))continue;product=data;base=url.startsWith('/api/')?region.habitat_feed:new URL(url,location.href).href;break;}catch{}}
    loading=false;render();}
  document.getElementById('load-forecast').addEventListener('click',load);setInterval(()=>{if(!document.hidden)load();},30*60000);load();
  return {refresh:load};
}
